import React, { useEffect, useState } from 'react';

const Loader = () => {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const iv = setInterval(() => {
      setProgress(p => {
        if (p >= 100) { clearInterval(iv); return 100; }
        return p + Math.random() * 12 + 3;
      });
    }, 120);
    return () => clearInterval(iv);
  }, []);

  return (
    <div style={{
      position: 'fixed', inset: 0,
      background: '#1a0f18',
      display: 'flex', flexDirection: 'column',
      alignItems: 'center', justifyContent: 'center',
      zIndex: 9999,
    }}>
      {/* Petal spinner */}
      <div style={{ position: 'relative', width: 90, height: 90, marginBottom: '2rem' }}>
        {[0,45,90,135,180,225,270,315].map((deg, i) => (
          <div key={deg} style={{
            position: 'absolute', top: '50%', left: '50%',
            width: 28, height: 14,
            marginTop: -7, marginLeft: -14,
            borderRadius: '50%',
            background: `linear-gradient(135deg, rgba(232,121,154,${0.4 + i * 0.07}), rgba(184,130,212,${0.3 + i * 0.06}))`,
            transform: `rotate(${deg}deg) translateX(26px)`,
            animation: `petal-spin 1.5s ease-in-out infinite`,
            animationDelay: `${i * 0.18}s`,
          }} />
        ))}
        <style>{`
          @keyframes petal-spin {
            0%, 100% { opacity: 0.35; transform: rotate(var(--r)) translateX(26px) scale(0.85); }
            50%       { opacity: 1;    transform: rotate(var(--r)) translateX(26px) scale(1.1); }
          }
        `}</style>
      </div>

      <div style={{
        fontFamily: "'Cormorant Garamond', serif",
        fontSize: '1.6rem', fontWeight: 600, fontStyle: 'italic',
        background: 'linear-gradient(135deg, #e8799a, #b882d4)',
        WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent',
        marginBottom: '1.8rem', letterSpacing: '0.05em',
      }}>
        Maithily M. Gondode
      </div>

      {/* Progress bar */}
      <div style={{
        width: 200, height: 3,
        background: 'rgba(253,240,244,0.08)',
        borderRadius: 2, overflow: 'hidden',
      }}>
        <div style={{
          height: '100%',
          width: `${Math.min(progress, 100)}%`,
          background: 'linear-gradient(90deg, #e8799a, #b882d4)',
          borderRadius: 2,
          transition: 'width 0.15s ease',
          boxShadow: '0 0 10px rgba(232,121,154,0.5)',
        }} />
      </div>
      <div style={{
        fontFamily: "'DM Mono', monospace",
        fontSize: '0.72rem', color: 'rgba(253,240,244,0.35)',
        marginTop: '0.75rem', letterSpacing: '0.15em',
      }}>Loading portfolio…</div>
    </div>
  );
};

export default Loader;
